// Parity gate for the JS port of the lusty-fuzzy matcher.
//
// files/quickshell/Helpers/Fuzzy.js is a port of the Rust crate (lusty repo:
// crates/lusty-fuzzy) that the tray menu filters with. Ports rot: this harness
// replays the golden vectors of files/quickshell/Helpers/tests/fuzzy-vectors.json
// (generated by `lusty --fuzzy-vectors`) against the JS implementation and fails
// on any difference in result count, order, score (1e-9) or match spans.
//
// Usage: check-fuzzy-parity.mjs [fixture.json] [--quiet]
// Exit status: 0 when every case matches, 1 otherwise (2 on unusable input).
import { readFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'

const here = dirname(fileURLToPath(import.meta.url))
const repo = join(here, '..', '..')
const QUIET = process.argv.includes('--quiet')
const args = process.argv.slice(2).filter((a) => !a.startsWith('--'))
const fixturePath = args[0] || join(repo, 'files/quickshell/Helpers/tests/fuzzy-vectors.json')
const fuzzyPath = join(repo, 'files/quickshell/Helpers/Fuzzy.js')

const SCORE_EPS = 1e-9

function loadFuzzy(path) {
  // The QML helper starts with `.pragma library`, which is not JavaScript.
  const src = readFileSync(path, 'utf8').replace(/^\.pragma library\s*$/m, '')
  return new Function(`${src}\nreturn Fuzzy`)()
}

function fmtSpans(spans) {
  return `[${spans.map(([a, b]) => `${a}-${b}`).join(', ')}]`
}

const fixture = JSON.parse(readFileSync(fixturePath, 'utf8'))
const Fuzzy = loadFuzzy(fuzzyPath)
let failures = 0
let checked = 0

if (Fuzzy.WEIGHTS_VERSION !== fixture.weights_version) {
  console.error(
    `weights_version mismatch: fixture=${fixture.weights_version} Fuzzy.js=${Fuzzy.WEIGHTS_VERSION} ` +
      '(regenerate scripts/dev/gen-fuzzy-vectors.sh)'
  )
  failures++
}

const opts = {
  anchor: fixture.anchor,
  layout: fixture.layout,
  foldCase: fixture.fold_case !== false,
}

// Cross-check inside the port: the lean scorer and the span extractor must
// agree (the crate asserts the same for Scorer::score vs score_with_spans).
for (const label of fixture.labels) {
  for (const testCase of fixture.cases) {
    const lean = Fuzzy.score(label, testCase.query)
    const full = Fuzzy.scoreWithSpans(label, testCase.query).score
    if (lean !== full) {
      console.error(`score paths disagree for ${JSON.stringify(label)} / ${JSON.stringify(testCase.query)}: ${lean} vs ${full}`)
      failures++
    }
  }
}

for (const testCase of fixture.cases) {
  const got = Fuzzy.rank(fixture.labels, testCase.query, opts)
  const want = testCase.results
  if (got.length !== want.length) {
    console.error(
      `case ${JSON.stringify(testCase.query)}: ${got.length} hits, fixture has ${want.length}\n` +
        `  got:  ${got.slice(0, 5).map((m) => `${JSON.stringify(m.label)} ${m.score.toFixed(6)}`).join('; ')}\n` +
        `  want: ${want.slice(0, 5).map((m) => `${JSON.stringify(m.label)} ${m.score.toFixed(6)}`).join('; ')}`
    )
    failures++
    continue
  }
  for (let i = 0; i < want.length; i++) {
    checked++
    const g = got[i]
    const w = want[i]
    const problems = []
    if (g.index !== w.index) problems.push(`index ${g.index} != ${w.index}`)
    if (Math.abs(g.score - w.score) > SCORE_EPS) problems.push(`score ${g.score} != ${w.score}`)
    const gs = JSON.stringify(g.spans)
    const ws = JSON.stringify(w.spans)
    if (gs !== ws) problems.push(`spans ${fmtSpans(g.spans)} != ${fmtSpans(w.spans)}`)
    if (problems.length) {
      console.error(`case ${JSON.stringify(testCase.query)} #${i} (${JSON.stringify(w.label)}): ${problems.join(', ')}`)
      failures++
    }
  }
}

// UI helpers around the spans are not part of the crate contract, but they are
// what the menu actually renders — check the two things that can break silently:
// byte→string range mapping and HTML escaping of third-party labels.
function checkMarkup(label, spans, expectStart, what) {
  const markup = Fuzzy.highlightMarkup(label, spans, 'color:#fff')
  if (!markup.startsWith(expectStart)) {
    console.error(`${what}: ${JSON.stringify(markup)} does not start with ${JSON.stringify(expectStart)}`)
    failures++
  }
}

if (typeof Fuzzy.highlightMarkup !== 'function') {
  console.error('Fuzzy.highlightMarkup is missing (DelegateEntry renders through it)')
  failures++
} else {
  checkMarkup('A <b> & q', [[0, 1]], "<span style='color:#fff'>A</span>", 'markup prefix')
  const escaped = Fuzzy.highlightMarkup('A <b> & q', [[0, 1]], 'color:#fff')
  if (escaped.includes('<b>') || !escaped.includes('&amp;')) {
    console.error(`markup is not escaped: ${JSON.stringify(escaped)}`)
    failures++
  }
  // "Настройки": byte span 0..10 covers the first five Cyrillic letters (two
  // bytes each) — the slice keeps the label's own casing ("Настр"), which is
  // exactly what the UI should draw.
  checkMarkup('Настройки', [[0, 10]], "<span style='color:#fff'>Настр</span>ойки", 'cyrillic byte span')
}

if (failures) {
  console.error(`check-fuzzy-parity: ${failures} problem(s)`)
  process.exit(1)
}
if (!QUIET) {
  console.log(
    `check-fuzzy-parity: ${fixture.cases.length} queries / ${checked} ranked entries match ` +
      `(weights_version ${fixture.weights_version}, anchor ${fixture.anchor}, layout ${fixture.layout})`
  )
}
